\begin{lemma}[Flat pullback is left exact]\leanok
  \label{lem:pullback_preserves_finite_limits}
  \lean{AlgebraicGeometry.pullback_preservesFiniteLimits}
  \uses{lem:sheafOfModules_pullbackIso, lem:forget_sheafOfModules_pfl_mathlib,
        lem:sheafification_pfl_mathlib, lem:presheaf_pullback_pfl_flat}
  If \(g\) is flat then \(g^*\) preserves finite limits. The flatness-dependent
  content reduces, via the factorisation of
  Lemma~\ref{lem:sheafOfModules_pullbackIso}, to the single middle factor
  (Lemma~\ref{lem:presheaf_pullback_pfl_flat}); the two outer factors are left-exact
  unconditionally.
\end{lemma}

\begin{proof}
  \uses{lem:sheafOfModules_pullbackIso, lem:forget_sheafOfModules_pfl_mathlib,
        lem:sheafification_pfl_mathlib, lem:presheaf_pullback_pfl_flat}
  By Lemma~\ref{lem:sheafOfModules_pullbackIso}, on the genuine scheme site \(g^*\)
  factors as the composite
  \(\operatorname{forget} \circ
  (\texttt{PresheafOfModules.pullback}\,\varphi_{\mathrm{hom}}) \circ
  \texttt{PresheafOfModules.sheafification}\). The outer two factors preserve finite
  limits unconditionally (Lemmas~\ref{lem:forget_sheafOfModules_pfl_mathlib}
  and~\ref{lem:sheafification_pfl_mathlib}, both supplied by Mathlib on the scheme

