\begin{lemma}[Flat pullback is left exact]
  \label{lem:pullback_preserves_finite_limits}
  \lean{AlgebraicGeometry.pullback_preservesFiniteLimits}
  \uses{lem:right_exact_mono_left_exact, lem:pullback_preserves_finite_colimits,
        lem:pullback_preserves_monos}
  If \(g\) is flat then \(g^*\) preserves finite limits.
\end{lemma}

\begin{proof}
  \uses{lem:right_exact_mono_left_exact, lem:pullback_preserves_finite_colimits,
        lem:pullback_preserves_monos}
  \(g^*\) is additive and preserves finite colimits, being a left adjoint
  (Lemma~\ref{lem:pullback_preserves_finite_colimits}), and it preserves monomorphisms because
  \(g\) is flat (Lemma~\ref{lem:pullback_preserves_monos}). Apply
  Lemma~\ref{lem:right_exact_mono_left_exact}.
\end{proof}

